const incident = $json;

const reportedAt = new Date(incident.reported_at);
const startedAt = new Date(incident.started_at);

const incidentDurationMinutes = Math.max(
  0,
  Math.round((reportedAt - startedAt) / 60000)
);

return [
  {
    json: {
      incident_id: incident.incident_id,
      reported_at: incident.reported_at,
      started_at: incident.started_at,
      incident_duration_minutes: incidentDurationMinutes,

      source: incident.source,
      country: incident.country,

      service: incident.service,
      payment_channel: incident.payment_channel,

      symptom: incident.symptom,
      error_code: incident.error_code,

      transactions_affected: incident.transactions_affected,
      estimated_transaction_value_mxn:
        incident.estimated_transaction_value_mxn,

      customer_impact: incident.customer_impact,
      financial_impact: incident.financial_impact,
      regulatory_impact: incident.regulatory_impact,

      known_changes: [
        "Authorization service release completed at 13:45"
      ],

      dependencies: [
        "payment-router",
        "external-processor",
        "fraud-engine"
      ],

      initial_observations: [
        "Authorization decline rate increased shortly after deployment",
        "Payment authorization latency remains within expected range",
        "Only the card-present payment channel appears affected"
      ],

      ai_governance: {
        severity_requires_human_validation: true,
        rca_is_hypothesis_only: true,
        production_actions_require_human_approval: true
      }
    }
  }
];

const classification = $json.output;

const historicalIncidents = [
  {
    incident_id: "PAY-HIST-001",
    title: "Payment Routing Configuration",
    symptoms: [
      "Elevated authorization declines after routing configuration update",
      "Payment authorization latency remained normal",
      "Specific payment traffic was affected"
    ],
    confirmed_rca: "Incorrect payment routing priority configuration",
    resolution: "Previous routing configuration restored after human approval",
    preventive_actions: [
      "Routing configuration validation",
      "Post-change payment smoke tests",
      "Routing decline-rate monitoring"
    ]
  },
  {
    incident_id: "PAY-HIST-002",
    title: "External Processor Connectivity",
    symptoms: [
      "Intermittent authorization timeouts",
      "Increased authorization latency",
      "Multiple payment channels affected"
    ],
    confirmed_rca: "External processor network instability",
    resolution: "Alternative processing path enabled after human approval",
    preventive_actions: [
      "Processor connectivity monitoring",
      "Failover validation",
      "External dependency health checks"
    ]
  },
  {
    incident_id: "PAY-HIST-003",
    title: "Fraud Rule Configuration",
    symptoms: [
      "Authorization platform remained healthy",
      "External processor remained healthy",
      "Fraud rejection rate increased significantly"
    ],
    confirmed_rca: "Incorrectly configured fraud threshold",
    resolution: "Fraud rule configuration rolled back after human approval",
    preventive_actions: [
      "Fraud rule peer review",
      "Pre-production rule validation",
      "Fraud rejection-rate monitoring"
    ]
  }
];

const ownershipMatrix = [
  {
    service: "payment-authorization",
    issue_type: "application",
    primary_owner_role: "Payments Platform Lead",
    backup_owner_role: "Application Support Lead"
  },
  {
    service: "payment-routing",
    issue_type: "configuration",
    primary_owner_role: "Payment Operations Lead",
    backup_owner_role: "Payments Platform Lead"
  },
  {
    service: "processor-connectivity",
    issue_type: "integration",
    primary_owner_role: "Integration Lead",
    backup_owner_role: "Payment Operations Lead"
  },
  {
    service: "fraud-engine",
    issue_type: "risk",
    primary_owner_role: "Fraud Platform Lead",
    backup_owner_role: "Risk Operations Lead"
  }
];

return [
  {
    json: {
      incident: $("Normalize Incident").first().json,
      impact_classification: classification,
      historical_incidents: historicalIncidents,
      ownership_matrix: ownershipMatrix,
      context_governance: {
        historical_cases_are_reference_only: true,
        similarity_does_not_confirm_root_cause: true,
        ownership_is_role_based: true
      }
    }
  }
];

const rcaOutput = $json.output;

const context = $("Add Incident Context").first().json;

const ownershipMatrix = context.ownership_matrix;

const domainMapping = {
  "authorization-service": {
    service: "payment-authorization",
    issue_type: "application"
  },
  "payment-router": {
    service: "payment-routing",
    issue_type: "configuration"
  },
  "fraud-engine": {
    service: "fraud-engine",
    issue_type: "risk"
  },
  "external-processor": {
    service: "processor-connectivity",
    issue_type: "integration"
  },
  "point-of-sale": {
    service: "payment-authorization",
    issue_type: "application"
  }
};

function findDomainKey(domain) {
  const normalized = domain.toLowerCase();

  return Object.keys(domainMapping).find(
    key => normalized.includes(key)
  );
}

const hypothesesWithOwnership = rcaOutput.hypotheses.map(hypothesis => {

  const domainKey = findDomainKey(hypothesis.suspected_domain);

  let ownership = {
    primary_owner_role: "Incident Commander to assign",
    backup_owner_role: "Incident Commander to assign",
    ownership_status: "Unmapped"
  };

  if (domainKey) {

    const mapping = domainMapping[domainKey];

    const matrixEntry = ownershipMatrix.find(
      entry =>
        entry.service === mapping.service &&
        entry.issue_type === mapping.issue_type
    );

    if (matrixEntry) {
      ownership = {
        primary_owner_role: matrixEntry.primary_owner_role,
        backup_owner_role: matrixEntry.backup_owner_role,
        ownership_status: "Mapped"
      };
    }
  }

  return {
    ...hypothesis,
    ownership
  };
});

return [
  {
    json: {
      incident: context.incident,
      impact_classification: context.impact_classification,

      rca_analysis: {
        rca_status: rcaOutput.rca_status,
        hypotheses: hypothesesWithOwnership,
        overall_assessment: rcaOutput.overall_assessment,
        requires_human_validation:
          rcaOutput.requires_human_validation
      },

      governance: {
        ownership_mapping_is_deterministic: true,
        owners_are_roles_not_individuals: true,
        rca_remains_unconfirmed: true,
        production_actions_require_human_approval: true
      }
    }
  }
];
